using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.XR;using UnityEngine.XR.Interaction.Toolkit;using UnityEngine.XR.Interaction.Toolkit.Inputs.Readers;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;using LighthouseKeepers.Gameplay.Interaction;using LighthouseKeepers.Lobby;
public static class TwoPeer{
 static WatchDemoController W=>UnityEngine.Object.FindAnyObjectByType<WatchDemoController>();static Unity.XR.CoreUtils.XROrigin Rig=>UnityEngine.Object.FindAnyObjectByType<Unity.XR.CoreUtils.XROrigin>();static HandRig Hand=>UnityEngine.Object.FindObjectsByType<HandRig>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(h=>h.Node==XRNode.RightHand);
 public static object Facts(){var c=W.State.Scare;var v=W.State.Recovery.Slot((int)CrewDuties.Other(W.CurrentDuty));return new{beat=(int)c.Beat,age=c.Age,attempt=c.Attempt,participants=c.Participants,reposition=c.Reposition,body=c.Body.ToString("F3"),duty=(int)W.CurrentDuty,caught=c.Caught,escaped=c.Escaped,localDown=W.State.Recovery.Downed((int)W.CurrentDuty),otherDown=v.down,otherProgress=v.progress,head=Rig.Camera.transform.position.ToString("F3"),valid=W.State.Capture(W.WaterHeight).Valid()};}
 public static object Pose(string where,string look){EditorUtility.audioMasterMute=true;var rig=Rig;foreach(var b in rig.GetComponentsInChildren<Behaviour>(true))if(b.GetType().Name.Contains("TrackedPose")||b.GetType().Name.Contains("InputModality")||b.GetType().Name=="DesktopPreview"||b.GetType().Name=="GravityProvider"||b.GetType().Name=="GroundedSlopeMovement")b.enabled=false;var safety=W.GetComponent<IslandSafety>();if(safety)safety.enabled=false;var cc=rig.GetComponent<CharacterController>();if(cc)cc.enabled=false;var p=where=="far"?new Vector3(2.95f,8.2f,0):where=="near1"?new Vector3(1.2f,8.25f,-1.5f):where=="near2"?new Vector3(1.2f,8.25f,-.8f):where=="victim"?new Vector3(1.5f,4.95f,1.3f):new Vector3(0,1.65f,-10.6f);rig.MoveCameraToWorldLocation(p);if(look=="child")rig.Camera.transform.LookAt(W.State.Scare.Body+Vector3.up*1.1f);else rig.Camera.transform.rotation=Quaternion.LookRotation(Vector3.right);Physics.SyncTransforms();return Facts();}
 public static object Look(string look){if(look=="child")Rig.Camera.transform.LookAt(W.State.Scare.Body+Vector3.up*1.1f);else Rig.Camera.transform.rotation=Quaternion.LookRotation(Vector3.right);return Facts();}
 public static object StageEscape(){var s=W.GetComponent<NightmareScene>();s.enabled=false;var c=W.State.Scare;for(int n=0;n<200&&c.Beat!=ScareBeat.Escape;n++)c.Tick(.1f,true,true,0,0);c.Place(HorrorTuning.Current.nightmareCorner,0);return Facts();}
 public static object EnableScene(){W.GetComponent<NightmareScene>().enabled=true;return true;}
 public static object PrepareRescue(){var r=Rig;var target=W.GetComponent<CrewRecovery>().Target((int)CrewDuties.Other(W.CurrentDuty));r.MoveCameraToWorldLocation(target.transform.position+Vector3.up*.55f-Vector3.forward*.4f);Hand.transform.parent.gameObject.SetActive(true);Hand.enabled=false;Hand.transform.parent.position=target.transform.position;Hand.Direct.enabled=true;Hand.Direct.selectInput=new XRInputButtonReader("test rescue grip",inputSourceMode:XRInputButtonReader.InputSourceMode.ManualValue);Hand.Direct.selectInput.QueueManualState(false,0);Physics.SyncTransforms();return Facts();}
 public static object Press(){Hand.Direct.selectInput.QueueManualState(true,1);return true;}public static object Release(){Hand.Direct.selectInput.QueueManualState(false,0);return true;}public static object Held()=>Hand.Direct.hasSelection;
}
